//! Replicated ceremony state, changed only by finalized blocks.
//!
//! Only public data lives here: configurations, dealer logs (a dealer's commitment plus every
//! player's signed acknowledgement) and the resulting public polynomial. Feldman-Desmedt lets a
//! dealer publish ("reveal") the private dealing of a player that did not acknowledge it; such
//! logs are refused, so no share material ever enters a block. The price is liveness: every player
//! must acknowledge a dealer for its log to count (see [Ceremonies::record]).
//!
//! A ceremony's key has an [Origin]: generated by this network's DKG, imported (an existing key
//! dealt offline by `mpc-keytool`, see `import`), or reshared (a new share generation of an
//! existing validator key, see [Reshare]). An imported key is registered complete, with the public
//! sharing of its manifest; a reshare completes like a DKG. The keyholders of both then
//! acknowledge, one by one and signed, that they verified and stored their share
//! ([Ceremonies::ready]). Every origin exposes the same [Ceremony::sharing], the only thing signing
//! uses.
//!
//! # Resharing (share generations)
//!
//! A validator key signs with the ceremony at its validator's `round` (`slashing`): its active
//! share generation. A reshare ceremony refreshes it with commonware's Feldman-Desmedt reshare
//! (Desmedt97): each dealer deals a fresh random polynomial whose constant term is its share of
//! the active generation (commonware refuses a dealing whose constant commitment is not that
//! share's public commitment), and each player interpolates the selected dealings at its own
//! index. The key does not change; every share does. The previous generation's public [Output] is
//! part of the ceremony ([Reshare::previous]): it fixes the dealers (that generation's players) and
//! enters the round's transcript. Today dealers and players are the same committee; the round
//! format already keeps them apart.

use super::{
    CeremonyConfig, CeremonyId, DEADLINE_BLOCKS, DkgStatus, Faults, GroupKey, MAX_ACTIVE,
    MAX_PARTICIPANTS, NAMESPACE, Unsupported, Variant,
};
use crate::{
    eth::duty::ValidatorKey,
    import::manifest::{Invalid, Manifest},
};
use bytes::{Buf, BufMut};
use commonware_codec::{
    Encode as _, EncodeSize, Error as CodecError, Read, ReadExt as _, Write, varint::UInt,
};
use commonware_cryptography::{
    Hasher as _, Sha256,
    bls12381::{
        dkg::feldman_desmedt::{
            DealerLog, DealerLogSummary, Failure, Info, Logs, Output, Reveal, SignedDealerLog,
            observe,
        },
        primitives::sharing::{Mode, ModeVersion, Sharing},
    },
    ed25519::{self, PrivateKey, PublicKey, Signature},
    sha256::Digest,
};
use commonware_parallel::Sequential;
use commonware_utils::{
    ordered::{Quorum as _, Set},
    union,
};
use rand_core::CryptoRng;
use serde::Serialize;
use std::collections::{BTreeMap, BTreeSet};
use tracing::warn;

/// A dealer log as submitted to consensus: signed by its dealer for one ceremony.
pub type SignedLog = SignedDealerLog<Variant, PrivateKey>;

/// One ceremony as every node sees it.
#[derive(Clone, Debug, PartialEq)]
pub struct Ceremony {
    pub config: CeremonyConfig,
    /// DKG round: ceremonies are numbered sequentially, failed ones included.
    pub round: u64,
    /// Height of the block that started the ceremony.
    pub started: u64,
    /// Digest of the configuration, round and starting block. It is part of the DKG namespace, so
    /// every signature of the ceremony (acks, logs) is bound to it and to this chain.
    pub session: Digest,
    pub status: DkgStatus,
    /// Accepted dealer logs. Once completed: exactly the logs that produced the key.
    pub logs: BTreeMap<PublicKey, DealerLog<Variant, PublicKey>>,
    /// Public result (group key and public polynomial), once completed. DKG only.
    pub output: Option<Output<Variant, PublicKey>>,
    pub origin: Origin,
}

/// Where a ceremony's key comes from.
#[derive(Clone, Debug, PartialEq)]
pub enum Origin {
    /// Generated by this network's DKG: `logs` and `output` hold its result.
    Dkg,
    /// An existing key dealt offline by a trusted dealer (`import`), registered by consensus.
    Imported(Box<Imported>),
    /// A new share generation of an existing validator key: `logs` and `output` hold its result,
    /// whose public key is the validator's.
    Reshare(Box<Reshare>),
}

/// The public state of a reshare ceremony.
#[derive(Clone, Debug, PartialEq)]
pub struct Reshare {
    /// The validator key whose shares are refreshed.
    pub validator: ValidatorKey,
    /// The generation refreshed: the round of the ceremony the key signed with when this one
    /// started.
    pub from: u64,
    /// That generation's public output. Its players are this round's dealers, each dealing its
    /// share of it.
    pub previous: Output<Variant, PublicKey>,
    /// Share indices whose keyholder acknowledged (signed) that it derived, verified and stored its
    /// new share.
    pub ready: BTreeSet<u32>,
}

/// The public state of an imported key.
#[derive(Clone, Debug, PartialEq)]
pub struct Imported {
    pub manifest: Manifest,
    /// The manifest's commitments: the public sharing every partial signature is checked against.
    pub sharing: Sharing<Variant>,
    /// Share indices whose keyholder acknowledged (signed) that it verified and stored its share.
    pub ready: BTreeSet<u32>,
}

/// Domain of [Ceremony::generation_id].
pub const GENERATION_NAMESPACE: &[u8] = b"_ETH_MPC_SIGNER_SHARE_GENERATION";

/// Domain of [ReadyAck] signatures (kept from when only imported keys used them; the round and
/// session it signs tell imported keys and reshares apart).
pub const READY_NAMESPACE: &[u8] = b"_ETH_MPC_SIGNER_IMPORTED_SHARE_READY";

/// A keyholder's statement, signed with its consensus identity, that it holds, verified against
/// the ceremony's public sharing, and durably stored its share of the key of `round`: an imported
/// key's share (opened from its envelope) or a reshare's new share (derived). It does not replace
/// any check: every keyholder verifies its own share before signing anything, and a coordinator
/// verifies every partial signature.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReadyAck {
    pub round: u64,
    /// The ceremony's session digest (an imported key's: its manifest digest).
    pub manifest: Digest,
    pub participant: PublicKey,
    pub signature: Signature,
}

impl ReadyAck {
    fn message(round: u64, manifest: &Digest) -> Vec<u8> {
        let mut message = round.to_be_bytes().to_vec();
        message.extend_from_slice(manifest.as_ref());
        message
    }

    pub fn sign(signer: &PrivateKey, round: u64, manifest: Digest) -> Self {
        Self {
            round,
            manifest,
            participant: commonware_cryptography::Signer::public_key(signer),
            signature: commonware_cryptography::Signer::sign(
                signer,
                READY_NAMESPACE,
                &Self::message(round, &manifest),
            ),
        }
    }

    pub fn is_valid(&self) -> bool {
        commonware_cryptography::Verifier::verify(
            &self.participant,
            READY_NAMESPACE,
            &Self::message(self.round, &self.manifest),
            &self.signature,
        )
    }
}

impl Write for ReadyAck {
    fn write(&self, buf: &mut impl BufMut) {
        UInt(self.round).write(buf);
        self.manifest.write(buf);
        self.participant.write(buf);
        self.signature.write(buf);
    }
}

impl Read for ReadyAck {
    type Cfg = ();

    fn read_cfg(buf: &mut impl Buf, _: &()) -> Result<Self, CodecError> {
        Ok(Self {
            round: UInt::read(buf)?.into(),
            manifest: Digest::read(buf)?,
            participant: PublicKey::read(buf)?,
            signature: Signature::read(buf)?,
        })
    }
}

impl EncodeSize for ReadyAck {
    fn encode_size(&self) -> usize {
        UInt(self.round).encode_size()
            + self.manifest.encode_size()
            + self.participant.encode_size()
            + self.signature.encode_size()
    }
}

/// Result of registering an imported key.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ImportOutcome {
    /// Registered as ceremony `round`.
    Registered(u64),
    /// The same manifest is already registered (idempotent).
    Exists(u64),
    /// The ceremony id is taken by another ceremony or another import.
    Conflict(u64),
    /// Ceremony `round` already holds this validator key: a key is registered once, so its
    /// slashing history can never be reset by registering it again.
    KeyExists(u64),
    /// The manifest is not a valid import for this committee.
    Invalid(Invalid),
}

/// Result of a `StartResharing` command.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ReshareOutcome {
    /// A new reshare ceremony was created with this round.
    Started(u64),
    /// The same reshare (id and key) was already started (idempotent).
    Exists(u64),
    /// The id is taken by another ceremony.
    Conflict(u64),
    /// Another reshare of this key (this round) is in progress or awaiting activation.
    Pending(u64),
    /// The key is not an activated validator key.
    UnknownValidator,
    NotActivated,
    /// The key's active ceremony has no public output to reshare.
    NoGeneration,
    /// The configuration cannot be run.
    Unsupported(Unsupported),
}

/// Result of an `ActivateGeneration` command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum GenerationOutcome {
    /// The reshare is now the key's active generation; the generation `from` is retired.
    Activated {
        from: u64,
    },
    /// It already is (idempotent).
    AlreadyActive,
    Refused(GenerationRefusal),
}

/// Result of an `AbortResharing` command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AbortOutcome {
    Aborted,
    /// It had already failed or been aborted (idempotent).
    AlreadyAborted,
    Refused(GenerationRefusal),
}

/// Why a generation is not activated, or a reshare not aborted.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, thiserror::Error)]
#[serde(rename_all = "snake_case", tag = "reason")]
pub enum GenerationRefusal {
    #[error("unknown validator public key")]
    UnknownValidator,
    #[error("not a reshare of this validator key")]
    NotReshare,
    #[error("the reshare is still in progress")]
    NotCompleted,
    #[error("the reshare failed or was aborted")]
    Aborted,
    /// It refreshes a generation that is no longer the active one.
    #[error("the reshare refreshes generation round {from}, but round {active} is active")]
    Stale { from: u64, active: u64 },
    #[error("{ready} of {required} keyholders acknowledged their new share")]
    NotReady { ready: u32, required: u32 },
    /// Abort: it is, or was, the active generation.
    #[error("the reshare is or was the active generation")]
    Active,
}

/// Why a share acknowledgement was not recorded.
#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
pub enum ReadyIgnored {
    #[error("no imported key or reshare awaiting shares at this round")]
    UnknownImport,
    #[error("acknowledgement for another manifest")]
    Manifest,
    #[error("not a participant")]
    NotParticipant,
    #[error("invalid signature")]
    BadSignature,
}

impl Ceremony {
    fn new(config: CeremonyConfig, round: u64, started: u64, block: &Digest) -> Self {
        let mut hasher = Sha256::default();
        hasher.update(NAMESPACE);
        hasher.update(&config.encode());
        hasher.update(&round.to_be_bytes());
        hasher.update(block.as_ref());
        Self {
            config,
            round,
            started,
            session: hasher.finalize().1,
            status: DkgStatus::InProgress,
            logs: BTreeMap::new(),
            output: None,
            origin: Origin::Dkg,
        }
    }

    /// The ceremony of an imported key registered in the block at `started`.
    fn new_imported(
        manifest: Manifest,
        sharing: Sharing<Variant>,
        round: u64,
        started: u64,
    ) -> Result<Self, Invalid> {
        Ok(Self {
            config: manifest.config()?,
            round,
            started,
            session: manifest.digest(),
            status: DkgStatus::Completed,
            logs: BTreeMap::new(),
            output: None,
            origin: Origin::Imported(Box::new(Imported {
                manifest,
                sharing,
                ready: BTreeSet::new(),
            })),
        })
    }

    /// The reshare ceremony started in the block at `started`: a new generation of `validator`'s
    /// key, dealt by the players of the generation `from` (its public output `previous`).
    fn new_reshare(
        config: CeremonyConfig,
        round: u64,
        started: u64,
        block: &Digest,
        validator: ValidatorKey,
        from: u64,
        previous: Output<Variant, PublicKey>,
    ) -> Self {
        let mut ceremony = Self::new(config, round, started, block);
        ceremony.origin = Origin::Reshare(Box::new(Reshare {
            validator,
            from,
            previous,
            ready: BTreeSet::new(),
        }));
        ceremony
    }

    /// The public sharing of the key (commitments and every participant's public share), once
    /// there is a key: what partial and group signatures are checked against, whatever the origin.
    pub fn sharing(&self) -> Option<&Sharing<Variant>> {
        match &self.origin {
            Origin::Dkg | Origin::Reshare(_) => self.output.as_ref().map(Output::public),
            Origin::Imported(imported) => Some(&imported.sharing),
        }
    }

    pub fn imported(&self) -> Option<&Imported> {
        match &self.origin {
            Origin::Imported(imported) => Some(imported),
            _ => None,
        }
    }

    pub fn reshare(&self) -> Option<&Reshare> {
        match &self.origin {
            Origin::Reshare(reshare) => Some(reshare),
            _ => None,
        }
    }

    /// Identifier of this ceremony's share generation, once it has a key: the SHA-256 of a
    /// namespace, the key, the round, the session (configuration, round, starting block) and the
    /// public sharing (commitments and participants' public shares). Two generations of a key
    /// never share it.
    pub fn generation_id(&self) -> Option<Digest> {
        let sharing = self.sharing()?;
        let mut hasher = Sha256::default();
        hasher.update(GENERATION_NAMESPACE);
        hasher.update(&sharing.public().encode());
        hasher.update(&self.round.to_be_bytes());
        hasher.update(self.session.as_ref());
        hasher.update(&sharing.encode());
        Some(hasher.finalize().1)
    }

    /// Share indices acknowledged as ready (imported keys and reshares).
    pub fn ready(&self) -> Option<&BTreeSet<u32>> {
        match &self.origin {
            Origin::Dkg => None,
            Origin::Imported(imported) => Some(&imported.ready),
            Origin::Reshare(reshare) => Some(&reshare.ready),
        }
    }

    /// The public output of this ceremony's key, as a reshare of it needs: the DKG's or reshare's
    /// output, or, for an imported key, one built from its registered sharing (its manifest digest
    /// as summary, the committee as dealers and players, nothing revealed).
    pub fn generation_output(&self) -> Option<Output<Variant, PublicKey>> {
        if self.status != DkgStatus::Completed {
            return None;
        }
        match &self.origin {
            Origin::Dkg | Origin::Reshare(_) => self.output.clone(),
            Origin::Imported(imported) => {
                let mut bytes = Vec::new();
                bytes.extend_from_slice(self.session.as_ref());
                imported.sharing.write(&mut bytes);
                self.config.participants.write(&mut bytes);
                self.config.participants.write(&mut bytes);
                Set::<PublicKey>::default().write(&mut bytes);
                Output::read_cfg(
                    &mut bytes.as_slice(),
                    &(MAX_PARTICIPANTS, ModeVersion::v0()),
                )
                .ok()
            }
        }
    }

    /// Feldman-Desmedt round information shared by every dealer, player and observer. A reshare's
    /// dealers are the previous generation's players.
    pub fn info(&self) -> Info<Variant, PublicKey> {
        let (previous, dealers) = match &self.origin {
            Origin::Reshare(reshare) => (
                Some(reshare.previous.clone()),
                reshare.previous.players().clone(),
            ),
            _ => (None, self.config.participants.clone()),
        };
        Info::new::<Faults>(
            &union(NAMESPACE, self.session.as_ref()),
            self.round,
            previous,
            Mode::NonZeroCounter,
            Reveal::V1,
            dealers,
            self.config.participants.clone(),
        )
        .expect("a non-empty committee forms a valid round (a reshare's previous output is checked when it starts)")
    }

    pub fn public_key(&self) -> Option<&GroupKey> {
        self.sharing().map(Sharing::public)
    }

    /// Fresh [Logs] holding the accepted logs.
    pub fn logs(&self) -> Logs<Variant, PublicKey, Faults> {
        let mut logs = Logs::new(self.info());
        for (dealer, log) in &self.logs {
            logs.record(dealer.clone(), log.clone());
        }
        logs
    }
}

/// Result of a `StartCeremony` command.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum StartOutcome {
    /// A new ceremony was created with this round.
    Started(u64),
    /// The same configuration was already started (idempotent).
    Exists(u64),
    /// The id is taken by a ceremony with a different configuration.
    Conflict(u64),
    /// The configuration cannot be run.
    Unsupported(Unsupported),
}

/// Why a dealer log was not recorded.
#[derive(Clone, Copy, Debug, PartialEq, Eq, thiserror::Error)]
pub enum Ignored {
    #[error("unknown ceremony")]
    UnknownCeremony,
    #[error("ceremony is not in progress")]
    Closed,
    #[error("signature does not match this ceremony")]
    BadSignature,
    #[error("dealer is not a participant")]
    NotParticipant,
    #[error("dealer already has a log")]
    Duplicate,
    #[error("log reveals private dealings")]
    Reveals,
}

/// Every ceremony, by round. Deterministic: same blocks, same state on every node.
pub struct Ceremonies {
    committee: Set<PublicKey>,
    ceremonies: BTreeMap<u64, Ceremony>,
    ids: BTreeMap<CeremonyId, u64>,
    /// Rounds changed since the last [Ceremonies::take_changed].
    changed: BTreeSet<u64>,
}

impl Ceremonies {
    pub fn new(committee: Set<PublicKey>) -> Self {
        Self {
            committee,
            ceremonies: BTreeMap::new(),
            ids: BTreeMap::new(),
            changed: BTreeSet::new(),
        }
    }

    /// Re-insert a ceremony loaded from storage.
    pub fn restore(&mut self, ceremony: Ceremony) {
        self.ids.insert(ceremony.config.id.clone(), ceremony.round);
        self.ceremonies.insert(ceremony.round, ceremony);
    }

    pub fn get(&self, id: &CeremonyId) -> Option<&Ceremony> {
        self.ids.get(id).map(|round| &self.ceremonies[round])
    }

    pub fn by_round(&self, round: u64) -> Option<&Ceremony> {
        self.ceremonies.get(&round)
    }

    pub fn iter(&self) -> impl Iterator<Item = &Ceremony> {
        self.ceremonies.values()
    }

    /// Ceremonies changed since the previous call.
    pub fn take_changed(&mut self) -> Vec<Ceremony> {
        std::mem::take(&mut self.changed)
            .into_iter()
            .map(|round| self.ceremonies[&round].clone())
            .collect()
    }

    /// Start `config` in the block at `height`. An id is never reused, whatever its outcome.
    pub fn start(&mut self, config: CeremonyConfig, height: u64, block: &Digest) -> StartOutcome {
        if let Some(&round) = self.ids.get(&config.id) {
            return if self.ceremonies[&round].config == config {
                StartOutcome::Exists(round)
            } else {
                StartOutcome::Conflict(round)
            };
        }
        if let Err(reason) = config.check(&self.committee) {
            return StartOutcome::Unsupported(reason);
        }
        let active = self
            .ceremonies
            .values()
            .filter(|ceremony| ceremony.status == DkgStatus::InProgress)
            .count();
        if active >= MAX_ACTIVE {
            return StartOutcome::Unsupported(Unsupported::TooManyActive);
        }

        let round = self.ceremonies.len() as u64;
        self.ids.insert(config.id.clone(), round);
        self.ceremonies
            .insert(round, Ceremony::new(config, round, height, block));
        self.changed.insert(round);
        StartOutcome::Started(round)
    }

    /// Register the imported key of `manifest` in the block at `height`, as the next round. An id
    /// and a key are each registered once, whatever ceremony holds them.
    pub fn import(&mut self, manifest: Manifest, height: u64) -> ImportOutcome {
        if let Some(&round) = self.ids.get(&manifest.ceremony) {
            let existing = &self.ceremonies[&round];
            return match existing.imported() {
                Some(imported) if imported.manifest == manifest => ImportOutcome::Exists(round),
                _ => ImportOutcome::Conflict(round),
            };
        }
        if let Some(existing) = self.ceremonies.values().find(|ceremony| {
            ceremony
                .public_key()
                .is_some_and(|key| key.encode().as_ref() == manifest.validator.as_slice())
        }) {
            return ImportOutcome::KeyExists(existing.round);
        }
        let sharing = match manifest.check(&self.committee) {
            Ok(sharing) => sharing,
            Err(invalid) => return ImportOutcome::Invalid(invalid),
        };
        let round = self.ceremonies.len() as u64;
        let ceremony = match Ceremony::new_imported(manifest, sharing, round, height) {
            Ok(ceremony) => ceremony,
            Err(invalid) => return ImportOutcome::Invalid(invalid),
        };
        self.ids.insert(ceremony.config.id.clone(), round);
        self.ceremonies.insert(round, ceremony);
        self.changed.insert(round);
        ImportOutcome::Registered(round)
    }

    /// Start a reshare of `validator`'s key, whose active generation is the ceremony `from`, as
    /// ceremony `id` in the block at `height`. One reshare of a key at a time: a later round of
    /// the same key that has not failed is either in progress, awaiting activation, or already the
    /// active generation (then `from` is it, and nothing later exists).
    pub fn reshare(
        &mut self,
        id: CeremonyId,
        validator: ValidatorKey,
        from: u64,
        height: u64,
        block: &Digest,
    ) -> ReshareOutcome {
        let config = CeremonyConfig::new(id, self.committee.clone());
        if let Some(&round) = self.ids.get(&config.id) {
            let existing = &self.ceremonies[&round];
            return match existing.reshare() {
                Some(reshare) if reshare.validator == validator && existing.config == config => {
                    ReshareOutcome::Exists(round)
                }
                _ => ReshareOutcome::Conflict(round),
            };
        }
        if let Some(pending) = self.ceremonies.values().find(|ceremony| {
            ceremony.round > from
                && ceremony.status != DkgStatus::Failed
                && ceremony
                    .reshare()
                    .is_some_and(|reshare| reshare.validator == validator)
        }) {
            return ReshareOutcome::Pending(pending.round);
        }
        let Some(previous) = self
            .ceremonies
            .get(&from)
            .filter(|ceremony| {
                ceremony
                    .public_key()
                    .is_some_and(|key| key.encode().as_ref() == validator.as_slice())
            })
            .and_then(Ceremony::generation_output)
        else {
            return ReshareOutcome::NoGeneration;
        };
        if let Err(reason) = config.check(&self.committee) {
            return ReshareOutcome::Unsupported(reason);
        }
        // The round must accept the previous output (consistent, enough dealers among its players).
        if Info::<Variant, PublicKey>::new::<Faults>(
            NAMESPACE,
            0,
            Some(previous.clone()),
            Mode::NonZeroCounter,
            Reveal::V1,
            previous.players().clone(),
            config.participants.clone(),
        )
        .is_err()
        {
            return ReshareOutcome::NoGeneration;
        }
        let active = self
            .ceremonies
            .values()
            .filter(|ceremony| ceremony.status == DkgStatus::InProgress)
            .count();
        if active >= MAX_ACTIVE {
            return ReshareOutcome::Unsupported(Unsupported::TooManyActive);
        }
        let round = self.ceremonies.len() as u64;
        self.ids.insert(config.id.clone(), round);
        self.ceremonies.insert(
            round,
            Ceremony::new_reshare(config, round, height, block, validator, from, previous),
        );
        self.changed.insert(round);
        ReshareOutcome::Started(round)
    }

    /// Abort the reshare `round` (in progress, or completed and not activated: the caller checks
    /// that it is not the active generation). Its shares are never used; the key keeps signing
    /// with its active generation. `false` if it had already failed.
    pub fn abort(&mut self, round: u64) -> bool {
        let Some(ceremony) = self.ceremonies.get_mut(&round) else {
            return false;
        };
        if ceremony.status == DkgStatus::Failed {
            return false;
        }
        ceremony.status = DkgStatus::Failed;
        self.changed.insert(round);
        true
    }

    /// Mark `round` changed (its role moved: the keyholders are told again).
    pub fn touch(&mut self, round: u64) {
        if self.ceremonies.contains_key(&round) {
            self.changed.insert(round);
        }
    }

    /// Record a keyholder's acknowledgement of its share of an imported key, or of a completed
    /// reshare. Returns its share index (also when it was already recorded).
    pub fn ready(&mut self, ack: &ReadyAck) -> Result<u32, ReadyIgnored> {
        let ceremony = self
            .ceremonies
            .get_mut(&ack.round)
            .ok_or(ReadyIgnored::UnknownImport)?;
        if ceremony.session != ack.manifest {
            return Err(ReadyIgnored::Manifest);
        }
        let index = ceremony
            .config
            .participants
            .index(&ack.participant)
            .ok_or(ReadyIgnored::NotParticipant)?
            .get();
        let completed = ceremony.status == DkgStatus::Completed;
        let ready = match &mut ceremony.origin {
            Origin::Imported(imported) => &mut imported.ready,
            Origin::Reshare(reshare) if completed => &mut reshare.ready,
            _ => return Err(ReadyIgnored::UnknownImport),
        };
        if !ack.is_valid() {
            return Err(ReadyIgnored::BadSignature);
        }
        if ready.insert(index) {
            self.changed.insert(ack.round);
        }
        Ok(index)
    }

    /// Record a dealer log for the ceremony `round`. The first valid log of each dealer wins.
    ///
    /// A log is only accepted if it is signed by a participant for this very ceremony and every
    /// player acknowledged the dealing (no reveals). The acknowledgement signatures and the
    /// commitment are verified later, by [observe], before any log is used.
    pub fn record(&mut self, round: u64, log: SignedLog) -> Result<PublicKey, Ignored> {
        let ceremony = self
            .ceremonies
            .get_mut(&round)
            .ok_or(Ignored::UnknownCeremony)?;
        if ceremony.status != DkgStatus::InProgress {
            return Err(Ignored::Closed);
        }
        let (dealer, log) = log.check(&ceremony.info()).ok_or(Ignored::BadSignature)?;
        if ceremony.config.participants.position(&dealer).is_none() {
            return Err(Ignored::NotParticipant);
        }
        if ceremony.logs.contains_key(&dealer) {
            return Err(Ignored::Duplicate);
        }
        match log.summary() {
            DealerLogSummary::Ok { reveals, .. } if reveals.is_empty() => {}
            _ => return Err(Ignored::Reveals),
        }
        ceremony.logs.insert(dealer.clone(), log);
        self.changed.insert(round);
        Ok(dealer)
    }

    /// End of the block at `height`: complete ceremonies that have enough valid logs and fail
    /// those past their deadline.
    pub fn advance(&mut self, height: u64, rng: &mut impl CryptoRng) {
        for (round, ceremony) in &mut self.ceremonies {
            if ceremony.status != DkgStatus::InProgress {
                continue;
            }
            let required = ceremony.config.participants.quorum::<Faults>() as usize;
            if ceremony.logs.len() >= required {
                match observe::<Variant, PublicKey, Faults, ed25519::Batch>(
                    rng,
                    ceremony.logs(),
                    &Sequential,
                ) {
                    Ok(output) => {
                        // Players must finalize with exactly the logs that produced the key.
                        ceremony
                            .logs
                            .retain(|dealer, _| output.dealers().position(dealer).is_some());
                        ceremony.output = Some(output);
                        ceremony.status = DkgStatus::Completed;
                        self.changed.insert(*round);
                        continue;
                    }
                    Err(Failure::InsufficientLogs { faults, .. }) => {
                        for (dealer, reason) in faults.iter_pairs() {
                            warn!(round, ?dealer, %reason, "dropping invalid dealer log");
                            ceremony.logs.remove(dealer);
                        }
                        self.changed.insert(*round);
                    }
                }
            }
            if height >= ceremony.started + DEADLINE_BLOCKS {
                ceremony.status = DkgStatus::Failed;
                self.changed.insert(*round);
            }
        }
    }
}

fn write_status(status: DkgStatus, buf: &mut impl BufMut) {
    (status as u8).write(buf);
}

fn read_status(buf: &mut impl Buf) -> Result<DkgStatus, CodecError> {
    match u8::read(buf)? {
        0 => Ok(DkgStatus::NotStarted),
        1 => Ok(DkgStatus::InProgress),
        2 => Ok(DkgStatus::Completed),
        3 => Ok(DkgStatus::Failed),
        tag => Err(CodecError::InvalidEnum(tag)),
    }
}

impl Write for Ceremony {
    fn write(&self, buf: &mut impl BufMut) {
        self.config.write(buf);
        UInt(self.round).write(buf);
        UInt(self.started).write(buf);
        self.session.write(buf);
        write_status(self.status, buf);
        UInt(self.logs.len() as u32).write(buf);
        for (dealer, log) in &self.logs {
            dealer.write(buf);
            log.write(buf);
        }
        self.output.is_some().write(buf);
        if let Some(output) = &self.output {
            output.write(buf);
        }
    }
}

impl Read for Ceremony {
    type Cfg = ();

    fn read_cfg(buf: &mut impl Buf, _: &()) -> Result<Self, CodecError> {
        let config = CeremonyConfig::read(buf)?;
        let round = UInt::read(buf)?.into();
        let started = UInt::read(buf)?.into();
        let session = Digest::read(buf)?;
        let status = read_status(buf)?;
        let count: u32 = UInt::read(buf)?.into();
        if count > MAX_PARTICIPANTS.get() {
            return Err(CodecError::Invalid("Ceremony", "too many logs"));
        }
        let mut logs = BTreeMap::new();
        for _ in 0..count {
            let dealer = PublicKey::read(buf)?;
            let log = DealerLog::read_cfg(buf, &MAX_PARTICIPANTS)?;
            logs.insert(dealer, log);
        }
        let output = if bool::read(buf)? {
            Some(Output::read_cfg(
                buf,
                &(MAX_PARTICIPANTS, ModeVersion::v0()),
            )?)
        } else {
            None
        };
        Ok(Self {
            config,
            round,
            started,
            session,
            status,
            logs,
            output,
            origin: Origin::Dkg,
        })
    }
}

impl Ceremony {
    /// Encoding of an imported key's ceremony (the DKG encoding is [Write] / [Read]): its
    /// manifest, round, starting block and acknowledged shares. Everything else derives from the
    /// manifest.
    pub fn write_imported(&self, buf: &mut impl BufMut) {
        let imported = self.imported().expect("an imported ceremony");
        imported.manifest.write(buf);
        UInt(self.round).write(buf);
        UInt(self.started).write(buf);
        UInt(imported.ready.len() as u32).write(buf);
        for index in &imported.ready {
            UInt(*index).write(buf);
        }
    }

    pub fn imported_encode_size(&self) -> usize {
        let imported = self.imported().expect("an imported ceremony");
        imported.manifest.encode_size()
            + UInt(self.round).encode_size()
            + UInt(self.started).encode_size()
            + UInt(imported.ready.len() as u32).encode_size()
            + imported
                .ready
                .iter()
                .map(|index| UInt(*index).encode_size())
                .sum::<usize>()
    }

    pub fn read_imported(buf: &mut impl Buf) -> Result<Self, CodecError> {
        let manifest = Manifest::read(buf)?;
        let round = UInt::read(buf)?.into();
        let started = UInt::read(buf)?.into();
        let count: u32 = UInt::read(buf)?.into();
        if count > MAX_PARTICIPANTS.get() {
            return Err(CodecError::Invalid("Ceremony", "too many acknowledgements"));
        }
        let ready = (0..count)
            .map(|_| UInt::read(buf).map(u32::from))
            .collect::<Result<BTreeSet<_>, _>>()?;
        let sharing = manifest
            .sharing()
            .map_err(|_| CodecError::Invalid("Ceremony", "imported commitments"))?;
        let mut ceremony = Self::new_imported(manifest, sharing, round, started)
            .map_err(|_| CodecError::Invalid("Ceremony", "imported manifest"))?;
        if let Origin::Imported(imported) = &mut ceremony.origin {
            imported.ready = ready;
        }
        Ok(ceremony)
    }
}

impl Ceremony {
    /// Encoding of a reshare ceremony: the DKG encoding ([Write]), then the key, the generation it
    /// refreshes, that generation's output and the acknowledged shares.
    pub fn write_reshare(&self, buf: &mut impl BufMut) {
        let reshare = self.reshare().expect("a reshare ceremony");
        self.write(buf);
        buf.put_slice(&reshare.validator);
        UInt(reshare.from).write(buf);
        reshare.previous.write(buf);
        UInt(reshare.ready.len() as u32).write(buf);
        for index in &reshare.ready {
            UInt(*index).write(buf);
        }
    }

    pub fn reshare_encode_size(&self) -> usize {
        let reshare = self.reshare().expect("a reshare ceremony");
        self.encode_size()
            + reshare.validator.len()
            + UInt(reshare.from).encode_size()
            + reshare.previous.encode_size()
            + UInt(reshare.ready.len() as u32).encode_size()
            + reshare
                .ready
                .iter()
                .map(|index| UInt(*index).encode_size())
                .sum::<usize>()
    }

    pub fn read_reshare(buf: &mut impl Buf) -> Result<Self, CodecError> {
        let mut ceremony = Self::read(buf)?;
        if buf.remaining() < 48 {
            return Err(CodecError::EndOfBuffer);
        }
        let mut validator = [0u8; 48];
        buf.copy_to_slice(&mut validator);
        let from = UInt::read(buf)?.into();
        let previous = Output::read_cfg(buf, &(MAX_PARTICIPANTS, ModeVersion::v0()))?;
        let count: u32 = UInt::read(buf)?.into();
        if count > MAX_PARTICIPANTS.get() {
            return Err(CodecError::Invalid("Ceremony", "too many acknowledgements"));
        }
        let ready = (0..count)
            .map(|_| UInt::read(buf).map(u32::from))
            .collect::<Result<BTreeSet<_>, _>>()?;
        ceremony.origin = Origin::Reshare(Box::new(Reshare {
            validator,
            from,
            previous,
            ready,
        }));
        Ok(ceremony)
    }
}

impl EncodeSize for Ceremony {
    fn encode_size(&self) -> usize {
        self.config.encode_size()
            + UInt(self.round).encode_size()
            + UInt(self.started).encode_size()
            + self.session.encode_size()
            + 1
            + UInt(self.logs.len() as u32).encode_size()
            + self
                .logs
                .iter()
                .map(|(dealer, log)| dealer.encode_size() + log.encode_size())
                .sum::<usize>()
            + 1
            + self.output.as_ref().map_or(0, EncodeSize::encode_size)
    }
}

